package com.bank.peak.service;

import java.util.logging.Logger;

// Finds the peak of a bitonic (rise-then-fall) price array.
public class PeakPriceService {
    private static final Logger log = Logger.getLogger(PeakPriceService.class.getName());

    public int dailyHigh(int[] prices) {
        int start = 0, end = prices.length - 1;
        while (start < end) {
            int mid = start + (end - start) / 2;
            if (prices[mid] > prices[mid + 1]) end = mid;      // falling: peak is here or left
            else start = mid + 1;                               // rising: peak is to the right
        }
        final int peak = prices[start];
        log.info(() -> "Daily high at index " + start + " = " + peak);
        return peak; // start == end points at the peak
    }
}
